INSERT INTO List_SpringDamperPhysics (SpringDamperPhysicsID, Ordinal, SuspensionPhysicsTypeID, UseProgressiveSpring, DefRideHeight, MinRideHeight, MaxRideHeight, MaxCompressHeight, DefSpringRate, MinSpringRate, MaxSpringRate, DefDampenBumpRate, MinDampenBumpRate, MaxDampenBumpRate, DampenBumpClamp, DefDampenReboundRate, MinDampenReboundRate, MaxDampenReboundRate, DampenReboundClamp, BumpstopStiffness, BumpstopDamping, ChassisPivotX, ChassisPivotY, TirePivotX, CamberChangeRatioCompression, CamberChangeRatioExpansion, StaticToe, StaticCamber, Caster, SteerRotAxisTireOffsetX, YMaxSpringVel, MaxStretchDeltaFromRideHeight) SELECT u.Ordinal * 1000 + 905, p.Ordinal, p.SuspensionPhysicsTypeID, p.UseProgressiveSpring, p.DefRideHeight, p.MinRideHeight, p.MaxRideHeight, p.MaxCompressHeight, p.DefSpringRate, p.MinSpringRate, p.MaxSpringRate, p.DefDampenBumpRate, p.MinDampenBumpRate, p.MaxDampenBumpRate, p.DampenBumpClamp, p.DefDampenReboundRate, p.MinDampenReboundRate, p.MaxDampenReboundRate, p.DampenReboundClamp, p.BumpstopStiffness, p.BumpstopDamping, p.ChassisPivotX, p.ChassisPivotY, p.TirePivotX, p.CamberChangeRatioCompression, p.CamberChangeRatioExpansion, p.StaticToe, -5.0, p.Caster, p.SteerRotAxisTireOffsetX, p.YMaxSpringVel, p.MaxStretchDeltaFromRideHeight FROM List_UpgradeSpringDamper u JOIN List_SpringDamperPhysics p ON p.SpringDamperPhysicsID = u.FrontSpringDamperPhysicsID WHERE u.Id = COALESCE((SELECT u2.Id FROM List_UpgradeSpringDamper u2 JOIN List_SpringDamperPhysics p2 ON p2.SpringDamperPhysicsID = u2.FrontSpringDamperPhysicsID WHERE u2.Ordinal = u.Ordinal AND p2.MinSpringRate < p2.MaxSpringRate AND p2.SuspensionPhysicsTypeID NOT IN (11,12,13,16,17,18,19,33,34) ORDER BY u2.Level DESC LIMIT 1), (SELECT u3.Id FROM List_UpgradeSpringDamper u3 WHERE u3.Ordinal = u.Ordinal AND u3.Id % 1000 <> 905 ORDER BY u3.Level DESC LIMIT 1)) AND NOT EXISTS (SELECT 1 FROM List_SpringDamperPhysics x WHERE x.SpringDamperPhysicsID = u.Ordinal * 1000 + 905);
INSERT INTO List_SpringDamperPhysics (SpringDamperPhysicsID, Ordinal, SuspensionPhysicsTypeID, UseProgressiveSpring, DefRideHeight, MinRideHeight, MaxRideHeight, MaxCompressHeight, DefSpringRate, MinSpringRate, MaxSpringRate, DefDampenBumpRate, MinDampenBumpRate, MaxDampenBumpRate, DampenBumpClamp, DefDampenReboundRate, MinDampenReboundRate, MaxDampenReboundRate, DampenReboundClamp, BumpstopStiffness, BumpstopDamping, ChassisPivotX, ChassisPivotY, TirePivotX, CamberChangeRatioCompression, CamberChangeRatioExpansion, StaticToe, StaticCamber, Caster, SteerRotAxisTireOffsetX, YMaxSpringVel, MaxStretchDeltaFromRideHeight) SELECT u.Ordinal * 1000 + 995, p.Ordinal, p.SuspensionPhysicsTypeID, p.UseProgressiveSpring, p.DefRideHeight, p.MinRideHeight, p.MaxRideHeight, p.MaxCompressHeight, p.DefSpringRate, p.MinSpringRate, p.MaxSpringRate, p.DefDampenBumpRate, p.MinDampenBumpRate, p.MaxDampenBumpRate, p.DampenBumpClamp, p.DefDampenReboundRate, p.MinDampenReboundRate, p.MaxDampenReboundRate, p.DampenReboundClamp, p.BumpstopStiffness, p.BumpstopDamping, p.ChassisPivotX, p.ChassisPivotY, p.TirePivotX, p.CamberChangeRatioCompression, p.CamberChangeRatioExpansion, -0.05, -1.0, p.Caster, p.SteerRotAxisTireOffsetX, p.YMaxSpringVel, p.MaxStretchDeltaFromRideHeight FROM List_UpgradeSpringDamper u JOIN List_SpringDamperPhysics p ON p.SpringDamperPhysicsID = u.RearSpringDamperPhysicsID WHERE u.Id = COALESCE((SELECT u2.Id FROM List_UpgradeSpringDamper u2 JOIN List_SpringDamperPhysics p2 ON p2.SpringDamperPhysicsID = u2.FrontSpringDamperPhysicsID WHERE u2.Ordinal = u.Ordinal AND p2.MinSpringRate < p2.MaxSpringRate AND p2.SuspensionPhysicsTypeID NOT IN (11,12,13,16,17,18,19,33,34) ORDER BY u2.Level DESC LIMIT 1), (SELECT u3.Id FROM List_UpgradeSpringDamper u3 WHERE u3.Ordinal = u.Ordinal AND u3.Id % 1000 <> 905 ORDER BY u3.Level DESC LIMIT 1)) AND NOT EXISTS (SELECT 1 FROM List_SpringDamperPhysics x WHERE x.SpringDamperPhysicsID = u.Ordinal * 1000 + 995);
INSERT INTO List_UpgradeSpringDamper (Id, Ordinal, Level, ManufacturerID, MassDiff, DragScale, WindInstabilityScale, Price, IsStock, SuspensionDamageModDefID, TiresDamageModDefID, FrontSpringDamperPhysicsID, RearSpringDamperPhysicsID) SELECT u.Ordinal * 1000 + 905, u.Ordinal, 5, u.ManufacturerID, u.MassDiff, u.DragScale, u.WindInstabilityScale, 2050, 0, u.SuspensionDamageModDefID, u.TiresDamageModDefID, u.Ordinal * 1000 + 905, u.Ordinal * 1000 + 995 FROM List_UpgradeSpringDamper u WHERE u.Id = COALESCE((SELECT u2.Id FROM List_UpgradeSpringDamper u2 JOIN List_SpringDamperPhysics p2 ON p2.SpringDamperPhysicsID = u2.FrontSpringDamperPhysicsID WHERE u2.Ordinal = u.Ordinal AND p2.MinSpringRate < p2.MaxSpringRate AND p2.SuspensionPhysicsTypeID NOT IN (11,12,13,16,17,18,19,33,34) ORDER BY u2.Level DESC LIMIT 1), (SELECT u3.Id FROM List_UpgradeSpringDamper u3 WHERE u3.Ordinal = u.Ordinal AND u3.Id % 1000 <> 905 ORDER BY u3.Level DESC LIMIT 1)) AND EXISTS (SELECT 1 FROM List_SpringDamperPhysics x WHERE x.SpringDamperPhysicsID = u.Ordinal * 1000 + 905) AND NOT EXISTS (SELECT 1 FROM List_UpgradeSpringDamper x WHERE x.Id = u.Ordinal * 1000 + 905) AND NOT EXISTS (SELECT 1 FROM List_UpgradeSpringDamper x WHERE x.Ordinal = u.Ordinal AND x.Level = 5);
